import random
from typing import List

class Pencil:
    def __init__(self, name: str, price: float, quantity: int, description: str):
        self.name = name
        self.price = price
        self.quantity = quantity
        self.description = description

    def calculate_total(self):
        return self.price * self.quantity

    def sell(self):
        self.quantity -= 1
        return self.calculate_total()

def buy_pencil(pencils: List[Pencil], user_name: str) -> None:
    """This function buys a pencil from the user."""
    print(f"Dear {user_name}, we have {pencils} pencils available. You can buy {pencils - 1} pencils.")

def sell_pencil(pencils: List[Pencil], user_name: str) -> None:
    """This function sells a pencil from the user."""
    print(f"Dear {user_name}, you have {pencils} pencils. You can buy {pencils - 1} pencils.")

def main():
    pencils = []
    user_name = input("What is your name? ")
    pencils.append(Pencil("Pencil", 5.0, 10, "Test pencil"))
    pencils.append(Pencil("Pen", 3.0, 5, "Test pen"))
    pencils.append(Pencil("Eraser", 1.0, 1, "Test eraser"))

    while True:
        print("1. Buy a pencil")
        print("2. Sell a pencil")
        print("3. Quit")

        user_choice = input("Enter your choice: ")
        if user_choice == "1":
            buy_pencil(pencils, user_name)
        elif user_choice == "2":
            sell_pencil(pencils, user_name)
        elif user_choice == "3":
            break
        else:
            print("Invalid choice. Please enter 1, 2, or 3.")

if __name__ == "__main__":
    main()
